import { readFile } from 'node:fs/promises';
import { build } from 'esbuild';
import { expect, it } from 'vitest';

// core.autocrlf=true can check the generated file out with CRLF; normalize CRLF->LF only, no other whitespace changes.
const lf = (bytes: Uint8Array) => Buffer.from(bytes).toString('utf8').replace(/\r\n/g, '\n');

it('checked-in sandbox payload matches its sources and build options', async () => {
  const output = 'apps/web/src/mg/sandbox.generated.js';
  const built = await build({
    entryPoints: ['apps/web/src/mg/sandbox-entry.tsx'], outfile: output, bundle: true, format: 'iife',
    platform: 'browser', target: 'es2022', minify: true, legalComments: 'inline',
    define: { 'process.env.NODE_ENV': '"production"' },
    banner: { js: '// SPDX-License-Identifier: AGPL-3.0-only\n// Generated by: npx tsx apps/web/src/mg/build-sandbox.ts; retains third-party notices (MIT, BSD-3-Clause).' },
    write: false,
  });
  expect(lf(built.outputFiles[0].contents)).toBe(lf(await readFile(output)));
});
